#!/usr/bin/env bash
#
# Build a browsable TYPO3 demo instance for manually testing EXT:headliner.
#
# Run from the project root with DDEV:
#     ddev composer install
#     ddev exec bash Build/Scripts/setup-demo-instance.sh
#
# Afterwards:
#     Frontend: https://headliner.ddev.site/
#     Backend:  https://headliner.ddev.site/typo3/   (user admin, random password printed at the end)
#
# The instance itself (config/, .Build/, var/, fileadmin uploads, database) is git-ignored and
# fully regenerated by this script — re-run it any time to get a clean instance.

set -euo pipefail

# Environment-parameterised so the same script seeds the DDEV demo (defaults below) and any CI
# instance (native MariaDB creds + a localhost BASE_URL).
BASE_URL="${BASE_URL:-https://${DDEV_SITENAME:-headliner}.ddev.site/}"
ADMIN_USER="${ADMIN_USER:-admin}"
# Local demo only: fixed default password unless ADMIN_PASS is given (e.g. by CI).
ADMIN_PASS="${ADMIN_PASS:-Password.1}"
DB_HOST="${DB_HOST:-db}"
DB_PORT="${DB_PORT:-3306}"
DB_NAME="${DB_NAME:-db}"
DB_USER="${DB_USER:-db}"
DB_PASS="${DB_PASS:-db}"
DB_ROOT_USER="${DB_ROOT_USER:-root}"
DB_ROOT_PASS="${DB_ROOT_PASS:-root}"

# Path-parameterised so the script can also seed another TYPO3 install (set TYPO3_BIN, default: .Build/bin/typo3).
TYPO3_BIN="${TYPO3_BIN:-.Build/bin/typo3}"

echo "› resetting the database for a clean install"
mysql -h "${DB_HOST}" -P "${DB_PORT}" -u "${DB_ROOT_USER}" -p"${DB_ROOT_PASS}" \
    -e "DROP DATABASE IF EXISTS \`${DB_NAME}\`; CREATE DATABASE \`${DB_NAME}\` CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;" 2>/dev/null

echo "› TYPO3 setup (database + admin user + site)"
"${TYPO3_BIN}" setup \
    --driver=mysqli --host="${DB_HOST}" --port="${DB_PORT}" --dbname="${DB_NAME}" --username="${DB_USER}" --password="${DB_PASS}" \
    --admin-username="${ADMIN_USER}" --admin-user-password="${ADMIN_PASS}" --admin-email=admin@example.com \
    --project-name=headliner --create-site="${BASE_URL}" --server-type=other --no-interaction --force

# Persist trusted hosts into settings.php (not additional.php, which DDEV manages for the default
# docroot). DDEV only writes its additional.php once the docroot exists at `ddev start`, so a
# first-run or volume install would otherwise reject the host (#1396795884). Writing settings.php
# makes every instance self-sufficient with no restart. (TYPO3_CONTEXT=Development from
# web_environment already gives the debug error page.)
echo "› configuring trusted hosts in settings.php"
"${TYPO3_BIN}" configuration:set SYS/trustedHostsPattern '.*'

echo "› finalising extensions and caches"
"${TYPO3_BIN}" extension:setup
"${TYPO3_BIN}" asset:publish || true
"${TYPO3_BIN}" cache:flush
# A fresh install can leave a stale empty page in the page cache; clear it directly.
mysql -h "${DB_HOST}" -P "${DB_PORT}" -u "${DB_USER}" -p"${DB_PASS}" "${DB_NAME}" -e "TRUNCATE cache_pages;" 2>/dev/null || true

cat <<EOF

Done.
  Frontend: ${BASE_URL}
  Backend:  ${BASE_URL}typo3/   (user: ${ADMIN_USER}  pass: ${ADMIN_PASS})
EOF
